/* Pedagogical AI, image OCR, voice input and offline quick reference. */
let buddyTurns=[];
let activeRecognition=null,currentStudyLesson=null,currentStudySignature='';
let ttsEnabled=localStorage.getItem('buddy-tts-enabled')==='1';
function stopBuddySpeech(){if('speechSynthesis'in window)window.speechSynthesis.cancel()}
function speakBuddy(text){if(!ttsEnabled||!('speechSynthesis'in window)||!text)return;stopBuddySpeech();const u=new SpeechSynthesisUtterance(text);u.lang='vi-VN';u.rate=.92;u.pitch=1;const voices=window.speechSynthesis.getVoices();u.voice=voices.find(v=>v.lang&&v.lang.toLowerCase().startsWith('vi'))||null;window.speechSynthesis.speak(u)}
function toggleBuddySpeech(){ttsEnabled=!ttsEnabled;localStorage.setItem('buddy-tts-enabled',ttsEnabled?'1':'0');if(!ttsEnabled)stopBuddySpeech();const b=$('#ttsToggle');if(b){b.textContent=ttsEnabled?'🔊 Tắt đọc':'🔈 Bật đọc';b.setAttribute('aria-pressed',String(ttsEnabled))}const last=[...buddyTurns].reverse().find(x=>x.role==='assistant');if(ttsEnabled&&last)speakBuddy(last.text)}
function generatedMathLessons(g){const out=[],add=(q,a,b,c,id)=>out.push({question:q,steps:[a,b,c],id:`${g}-generated-${id}`});for(let i=1;i<=40;i++){const x=i+2,a=i%4+2,b=i+3,c=a*x+b;if(g===6){add(`Tìm x: ${a}x + ${b} = ${c}`,`Muốn giữ phần có x riêng, em cần xử lý số ${b} trước. Hãy chọn phép tính làm ở cả hai vế.`,`Trừ ${b} ở cả hai vế để được ${a}x = ${c-b}. Em hãy chia tiếp hai vế cho ${a}.`,`x = ${x}. Thay lại: ${a} × ${x} + ${b} = ${c}.`,`eq-${i}`);const w=i+4,h=i+2;add(`Hình chữ nhật dài ${w} cm, rộng ${h} cm. Tính chu vi.`,`Nhắc lại: chu vi hình chữ nhật bằng hai lần tổng chiều dài và chiều rộng. Em hãy viết phép tính trong ngoặc.`,`Tổng hai cạnh là ${w} + ${h} = ${w+h}. Bây giờ nhân kết quả với 2.`,`Chu vi là 2 × ${w+h} = ${2*(w+h)} cm.`,`geo-${i}`)}else if(g===7){const k=i+2;add(`Tìm x biết x/${k} = ${i+1}/${k+1}.`,`Đây là tỉ lệ thức. Em hãy nhân chéo hai tích trước.`,`Ta có (${k+1})x = ${k*(i+1)}. Hãy chia hai vế cho ${k+1}.`,`x = ${k*(i+1)}/${k+1}. Có thể rút gọn phân số nếu cần.`,`ratio-${i}`);const price=(i+2)*100,percent=(i%4+1)*5;add(`Một món đồ giá ${price}.000 đồng được giảm ${percent}%. Tính số tiền được giảm.`,`Đổi ${percent}% thành phân số trên 100 rồi nhân với giá ban đầu.`,`Số tiền giảm là ${price*1000} × ${percent}/100. Em hãy thực hiện phép nhân và phép chia.`,`Số tiền được giảm là ${price*percent*10} đồng.`,`pct-${i}`)}else if(g===8){const rhs=a*(x-i)+b;add(`Giải phương trình ${a}(x − ${i}) + ${b} = ${rhs}`,`Khai triển vế trái bằng tính chất phân phối. Đừng chia ngay khi còn ngoặc.`,`Sau khi khai triển, chuyển ${b} và −${a*i} sang vế phải để giữ ${a}x riêng.`,`Phương trình có nghiệm x = ${x}. Hãy thay lại để kiểm tra.`,`linear-${i}`);const n=i+2,m=i+3;add(`Phân tích x² − ${n+m}x + ${n*m} thành nhân tử.`,`Tìm hai số có tổng bằng ${n+m} và tích bằng ${n*m}.`,`Hai số đó là ${n} và ${m}. Hãy viết thành tích hai nhị thức.`,`x² − ${n+m}x + ${n*m} = (x − ${n})(x − ${m}).`,`factor-${i}`)}else if(g===9){const y=i+1,sum=x+y,diff=x-y;add(`Giải hệ x + y = ${sum}; x − y = ${diff}.`,`Cộng hai phương trình để khử y. Em hãy tính vế trái và vế phải sau khi cộng.`,`Ta được 2x = ${2*x}. Hãy tìm x rồi thay vào phương trình đầu để tìm y.`,`Nghiệm của hệ là (x; y) = (${x}; ${y}).`,`system-${i}`);const n=i+1,m=i+2;add(`Giải phương trình x² − ${n+m}x + ${n*m} = 0.`,`Tìm hai số có tổng ${n+m} và tích ${n*m} để phân tích vế trái.`,`Vế trái bằng (x − ${n})(x − ${m}). Hãy cho từng thừa số bằng 0.`,`Phương trình có hai nghiệm x = ${n} và x = ${m}.`,`quad-${i}`)}else if(g===10){const n=i+1,m=i+3;add(`Giải bất phương trình (x − ${n})(x − ${m}) < 0.`,`Xác định hai nghiệm biên ${n} và ${m}, rồi xét dấu tích trên ba khoảng.`,`Hệ số của x² dương nên tích âm ở khoảng nằm giữa hai nghiệm.`,`Tập nghiệm là ${n} < x < ${m}.`,`ineq-${i}`);const u=i+1,v=i+2,p=i+3,q=-(i+1);add(`Cho vectơ a = (${u}; ${v}), b = (${p}; ${q}). Tính a·b.`,`Tích vô hướng bằng tích các hoành độ cộng tích các tung độ. Em hãy viết phép tính.`,`a·b = ${u}×${p} + ${v}×(${q}). Hãy tính hai tích trước.`,`a·b = ${u*p+v*q}.`,`vector-${i}`)}else if(g===11){const first=i+1,d=i+2,n=6;add(`Cấp số cộng có u₁ = ${first}, công sai d = ${d}. Tính u₆.`,`Dùng công thức uₙ = u₁ + (n − 1)d. Hãy thay n = 6.`,`u₆ = ${first} + 5 × ${d}. Em hãy tính phép nhân trước.`,`u₆ = ${first+5*d}.`,`seq-${i}`);const total=i+5,choose=2;add(`Có ${total} học sinh. Có bao nhiêu cách chọn ${choose} bạn?`,`Vì không xét thứ tự, em dùng tổ hợp C(${total}, ${choose}).`,`C(${total}, 2) = ${total}×${total-1}/2. Hãy thực hiện phép tính.`,`Có ${total*(total-1)/2} cách chọn.`,`comb-${i}`)}else if(g===12){const power=i%4+2,coef=i+1;add(`Tính đạo hàm f(x) = ${coef}x^${power} + ${i}.`,`Đạo hàm hằng số bằng 0. Với x^n, hạ số mũ xuống làm hệ số.`,`f′(x) = ${coef} × ${power} × x^${power-1}. Em hãy nhân hai hệ số.`,`f′(x) = ${coef*power}x^${power-1}.`,`derivative-${i}`);const p=i%3+1;add(`Tính ∫₀¹ ${p+1}x^${p} dx.`,`Tăng số mũ thêm 1 rồi chia cho số mũ mới để tìm nguyên hàm.`,`Một nguyên hàm là x^${p+1}. Hãy thay cận 1 và 0.`,`Giá trị tích phân bằng 1.`,`integral-${i}`)}}return out}
function lessonPool(){
 const base=subject==='Toán'?mathLessonsByGrade[grade]:(lessons[level][subject]||lessons[level]['Toán']);
 const rows=subject==='Toán'?(mathBanksByGrade[grade]||[]):((banks[level]&&banks[level][subject])||[]);
 const extras=rows.map((row,i)=>({question:row[0]+' '+row[1].map((x,n)=>`${String.fromCharCode(65+n)}. ${x}`).join(' · '),steps:[`Đọc kỹ đề và xác định kiến thức cần dùng. Em hãy loại trước một lựa chọn chắc chắn chưa đúng.`,`So sánh các lựa chọn còn lại bằng cách thực hiện một phép tính hoặc tìm từ khóa quan trọng. Em chọn phương án nào?`,row[3]],id:`${grade}-${subject}-${i}`}));
 return [{...base,id:`${grade}-${subject}-sample`},...extras,...(subject==='Toán'?generatedMathLessons(grade):[])];
}
function chooseStudyLesson(force=false){const signature=`${grade}-${subject}`;const pool=lessonPool();if(!force&&currentStudyLesson&&currentStudySignature===signature)return currentStudyLesson;const previous=currentStudyLesson?.id;const choices=pool.filter(x=>x.id!==previous);currentStudyLesson=choices[Math.floor(Math.random()*choices.length)]||pool[0];currentStudySignature=signature;step=0;return currentStudyLesson}
const offlineReference={version:1,formulas:[
 {grade:'6–7',title:'Tỉ lệ thức',value:'a / b = c / d  ⇒  a × d = b × c'},
 {grade:'7–9',title:'Pythagore',value:'Trong tam giác vuông: a² + b² = c²'},
 {grade:'8–9',title:'Hằng đẳng thức',value:'(a + b)² = a² + 2ab + b²'},
 {grade:'8–9',title:'Phương trình bậc nhất',value:'ax + b = 0  ⇒  x = −b/a (a ≠ 0)'},
 {grade:'10–12',title:'Phương trình bậc hai',value:'Δ = b² − 4ac; x = (−b ± √Δ) / 2a'},
 {grade:'10–12',title:'Đạo hàm lũy thừa',value:"(xⁿ)' = n·xⁿ⁻¹"}
],examples:[
 '2x + 5 = 17: bước đầu hãy chuyển 5 sang vế phải.',
 '(x − 2)/3 + (x + 1)/2 = 4: bước đầu hãy tìm BCNN của 3 và 2.',
 'Tam giác vuông có hai cạnh góc vuông: bắt đầu bằng định lý Pythagore.'
]};
try{localStorage.setItem('buddy-offline-reference-v1',JSON.stringify(offlineReference))}catch{}
function renderOfflineReference(){const rows=offlineReference.formulas.filter(x=>grade<=9?!x.grade.startsWith('10'):x.grade.startsWith('10'));return `<details class="offline-reference"><summary>⌁ Công thức & bài mẫu dùng khi mất mạng</summary><div class="offline-reference-grid">${rows.map(x=>`<article><small>${x.grade}</small><b>${x.title}</b><code>${x.value}</code></article>`).join('')}</div><p>Dữ liệu này đã được lưu trên thiết bị và có thể mở lại khi mạng yếu.</p></details>`}
renderStudy=function(){
 let l=chooseStudyLesson();lessonContext={title:l.question,hint:l.steps[step]};if(!lessons[level][subject]&&subject!=='Toán')subject='Toán';
 content.innerHTML=`<h1>Cùng nghĩ, cùng hiểu bài ✧</h1><p class="muted">Buddy chỉ gợi ý đúng một bước mỗi lượt để bạn tự tìm ra lời giải.</p><div class="workspace study-workspace"><div class="tabs">${['Toán','Ngữ văn','Lịch sử'].map(t=>`<button class="chip ${subject===t?'selected':''}" data-subject="${t}">${t}</button>`).join('')}</div><section class="panel lesson-card"><span class="eyebrow">BÀI MẪU · KHỐI ${grade}</span><h2>${l.question}</h2><div class="bubble lesson-hint" aria-live="polite">${l.steps[step]}</div><div class="actions"><button class="primary" id="nextStep">${step<2?'Xem gợi ý tiếp theo →':'Thử lại từ đầu ↺'}</button><button class="secondary" id="newLesson">Bài khác ↻</button><button class="secondary" id="practice">Luyện câu hỏi cùng môn</button></div></section>${renderOfflineReference()}<section class="panel buddy-chat"><div class="panel-head"><div><span class="eyebrow">SMART BUDDY BOT</span><h2>Hỏi từng bước</h2></div><div class="chat-head-actions"><button class="secondary compact" type="button" id="ttsToggle" aria-pressed="${ttsEnabled}">${ttsEnabled?'🔊 Tắt đọc':'🔈 Bật đọc'}</button><span class="privacy-chip">🔒 API ở máy chủ</span></div></div><div class="chat-transcript" id="chatTranscript" aria-live="polite">${buddyTurns.length?buddyTurns.map(t=>`<div class="chat-message ${t.role}"><b>${t.role==='user'?'Bạn':'Buddy'}</b><p>${esc(t.text)}</p></div>`).join(''):'<div class="chat-empty">Bạn có thể gõ, đọc câu hỏi bằng giọng nói hoặc chụp đề bài.</div>'}</div><div class="notice">Buddy không đưa đáp số ngay. Mỗi lượt chỉ có một gợi ý và một câu hỏi để bạn làm tiếp.</div><label class="habit"><input id="ageConfirmed" type="checkbox"><span>Tôi từ 13 tuổi trở lên</span></label><form class="chat-composer" id="askForm"><label class="sr" for="askInput">Câu hỏi của bạn</label><textarea id="askInput" maxlength="1000" rows="3" placeholder="Ví dụ: tim x 2x+5=17 ko hieu"></textarea><div class="input-tools"><label class="input-tool" for="problemImage">▧ Chụp/tải đề<input id="problemImage" type="file" accept="image/png,image/jpeg,image/webp" capture="environment"></label><button class="input-tool" type="button" id="voiceInput" aria-pressed="false">◉ Nói câu hỏi</button><span id="inputStatus" role="status"></span><button class="primary send-ai" type="submit">Gửi cho Buddy ↗</button></div></form><div class="notice" id="askStatus" role="status">Đang kiểm tra kết nối AI…</div></section></div>`;
 document.querySelectorAll('[data-subject]').forEach(b=>b.onclick=()=>{subject=b.dataset.subject;step=0;buddyTurns=[];render()});
 $('#nextStep').onclick=()=>{step=(step+1)%3;render()};$('#newLesson').onclick=()=>{chooseStudyLesson(true);buddyTurns=[];render()};$('#practice').onclick=()=>{question=0;score=0;answered=false;navigate('quiz')};
 $('#askForm').onsubmit=sendAIQuestion;$('#problemImage').onchange=readProblemImage;$('#voiceInput').onclick=startVoiceInput;$('#ttsToggle').onclick=toggleBuddySpeech;checkAIStatus();
};
async function readProblemImage(e){const file=e.target.files?.[0],status=$('#inputStatus'),input=$('#askInput');if(!file)return;if(!/^image\/(png|jpeg|webp)$/.test(file.type)||file.size>5*1024*1024){status.textContent='Ảnh phải là PNG/JPG/WEBP và không quá 5 MB.';return}if(!$('#ageConfirmed').checked){status.textContent='Hãy xác nhận độ tuổi trước khi gửi ảnh.';return}status.textContent='Đang đọc chữ trong ảnh…';try{const fileData=await new Promise((ok,no)=>{const r=new FileReader();r.onload=()=>ok(r.result);r.onerror=no;r.readAsDataURL(file)});const res=await fetch('/api/tools',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action:'ocr',grade,ageConfirmed:true,fileData,fileType:file.type}),signal:AbortSignal.timeout(60000)});const data=await res.json();if(!res.ok)throw Error(data.message||'Không đọc được ảnh.');input.value=[input.value.trim(),data.result].filter(Boolean).join('\n');status.textContent='Đã chép đề từ ảnh. Bạn hãy kiểm tra lại ký hiệu.'}catch(err){status.textContent=err.name==='TimeoutError'||err.name==='TypeError'?'Kết nối lỗi khi đọc ảnh.':err.message}finally{e.target.value=''}}
function startVoiceInput(){const button=$('#voiceInput'),status=$('#inputStatus'),input=$('#askInput');if(activeRecognition){activeRecognition.stop();return}const SR=window.SpeechRecognition||window.webkitSpeechRecognition;if(!SR){status.textContent='Trình duyệt này chưa hỗ trợ nhập giọng nói. Bạn có thể dùng bàn phím giọng nói của điện thoại.';return}const r=new SR();activeRecognition=r;r.lang='vi-VN';r.interimResults=false;r.continuous=true;r.maxAlternatives=1;button.textContent='■ Tắt nói';button.setAttribute('aria-pressed','true');status.textContent='Đang nghe… Nhấn “Tắt nói” khi xong.';r.onresult=e=>{let text='';for(let i=e.resultIndex;i<e.results.length;i++)if(e.results[i].isFinal)text+=e.results[i][0].transcript+' ';if(text.trim())input.value=[input.value.trim(),text.trim()].filter(Boolean).join(' ')};r.onerror=e=>{if(e.error!=='aborted')status.textContent='Chưa nghe rõ. Hãy thử lại ở nơi yên tĩnh.'};r.onend=()=>{activeRecognition=null;if(button.isConnected){button.textContent='◉ Nói câu hỏi';button.setAttribute('aria-pressed','false')}if(status.textContent.startsWith('Đang nghe'))status.textContent=input.value.trim()?'Đã dừng nói và nhập nội dung.':'Đã tắt nói.'};r.start()}
sendAIQuestion=async function(e){e.preventDefault();const form=e.currentTarget,input=$('#askInput'),status=$('#askStatus'),q=input.value.trim();if(!q){status.textContent='Bạn hãy nhập câu hỏi trước nhé.';return}if(!$('#ageConfirmed').checked){status.textContent='Phần AI dành cho người từ 13 tuổi trở lên.';return}const button=form.querySelector('.send-ai');button.disabled=true;button.textContent='Đang suy nghĩ…';status.className='notice';status.textContent='Buddy đang chọn đúng một bước gợi ý…';const history=buddyTurns.slice(-8).map(x=>({role:x.role,text:x.text}));try{const r=await fetch('/api/ask',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({question:q,level,grade,subject,context:lessonContext,turns:history,ageConfirmed:true}),signal:AbortSignal.timeout(85000)});let data;try{data=await r.json()}catch{throw Error('Máy chủ AI chưa trả dữ liệu hợp lệ.')}if(!r.ok)throw Error(data.message||'Máy chủ gặp lỗi.');if(typeof data.answer!=='string'||!data.answer.trim())throw Error('AI chưa trả lời. Hãy thử lại.');buddyTurns.push({role:'user',text:q},{role:'assistant',text:data.answer.trim()});buddyTurns=buddyTurns.slice(-10);input.value='';const transcript=$('#chatTranscript');transcript.innerHTML=buddyTurns.map(t=>`<div class="chat-message ${t.role}"><b>${t.role==='user'?'Bạn':'Buddy'}</b><p>${esc(t.text)}</p></div>`).join('');transcript.scrollTop=transcript.scrollHeight;speakBuddy(data.answer.trim());status.textContent='Buddy đã gợi ý một bước. Bạn hãy thử làm rồi trả lời tiếp.'}catch(err){status.textContent=err.name==='TimeoutError'||err.name==='TypeError'?'Kết nối lỗi hoặc quá thời gian chờ. Hãy kiểm tra mạng rồi thử lại.':err.message}finally{if(button.isConnected){button.disabled=false;button.textContent='Gửi cho Buddy ↗'}}};
